topic_id = 1158
title = "Wildlife Sanctuaries (Abhyaranya) Master Quiz"
title_hi = "वन्यजीव अभयारण्य (Abhyaranya) मास्टर क्विज़"
desc = "Master Chhattisgarh's Wildlife Sanctuaries with this highly focused CGPSC Prelims quiz. Test your knowledge on the exact establishment years, areas, districts, and specific wildlife of the 11 sanctuaries."
desc_hi = "इस अत्यधिक केंद्रित सीजीपीएससी प्रीलिम्स क्विज़ के साथ छत्तीसगढ़ के वन्यजीव अभयारण्यों पर अपनी पकड़ मजबूत करें। 11 अभयारण्यों के सटीक स्थापना वर्षों, क्षेत्रों, जिलों और विशिष्ट वन्यजीवों पर अपने ज्ञान का परीक्षण करें।"
total_q = len(rows)
time_limit = total_q
